def print_table(headers: list, data: list) -> None:
    """Print a table from headers and data rows."""
    # Calculate the maximum width for each column
    max_widths = [len(header) for header in headers]
    for row in data:
        for i, item in enumerate(row):
            max_widths[i] = max(max_widths[i], len(str(item)))

    # Format and print the table
    for i, header in enumerate(headers):
        print(f"| {header.ljust(max_widths[i])} |", end='')
    print()

    for row in data:
        for i, item in enumerate(row):
            print(f"| {str(item).ljust(max_widths[i])} |", end='')
        print()

import bcrypt

# Hash a password
def hash_password(password: str):
    # Generate a salt and hash the password
    salt = bcrypt.gensalt()
    hashed_pw = bcrypt.hashpw(password.encode('utf-8'), salt)
    return hashed_pw.decode('utf-8')

# Verify a password
def verify_password(password: str, hashed_pw: str):
    # Check if the password matches the hashed password
    return bcrypt.checkpw(password.encode('utf-8'), hashed_pw.encode('utf-8'))

