import sys

def format_record(record, headers):
    """Format a record as a string with aligned columns."""
    return ' | '.join(str(record.get(header, '')) for header in headers)

def format_table(records, headers):
    """Format a list of records as a table with aligned columns."""
    # Get the maximum width for each column
    max_widths = {header: max(len(str(record.get(header, ''))) for record in records) for header in headers}

    # Format the header row
    header_row = ' | '.join(header.ljust(max_widths[header]) for header in headers)

    # Format the data rows
    data_rows = [
        ' | '.join(str(record.get(header, '')).ljust(max_widths[header]) for header in headers)
        for record in records
    ]

    # Join all rows with newlines
    return '\n'.join([header_row] + data_rows)

def print_table(records, headers):
    """Print a list of records as a formatted table in the terminal."""
    table = format_table(records, headers)
    print(textwrap.fill(table, width=120))

