import time

def cache_with_ttl(func, ttl_seconds):
    cache = {}

    def wrapper(*args, **kwargs):
        key = (args, frozenset(kwargs.items()))
        if key in cache:
            current_time = time.time()
            if current_time - cache[key][0] < ttl_seconds:
                return cache[key][1]

        result = func(*args, **kwargs)
        cache[key] = (time.time(), result)
        return result

    return wrapper

