class TTLCache:
    """A cache that stores results with a time-to-live (TTL)."""

    def __init__(self, maxsize: int = 128, ttl: float = 60.0):
        self.maxsize = maxsize
        self.ttl = ttl
        self.cache = {}
        self.lock = Lock()

    def __getitem__(self, key: Any) -> Any:
        with self.lock:
            if key not in self.cache:
                return None

            item = self.cache[key]
            if time.time() - item['timestamp'] > self.ttl:
                self.cache.pop(key)
                return None

            return item['value']

    def __setitem__(self, key: Any, value: Any) -> None:
        with self.lock:
            if self.maxsize > 0 and len(self.cache) >= self.maxsize:
                # Remove the oldest item
                oldest = min(self.cache.items(), key=lambda x: x[1]['timestamp'])
                self.cache.pop(oldest[0])

            self.cache[key] = {
                'value': value,
                'timestamp': time.time()
            }

    def __contains__(self, key: Any) -> bool:
        with self.lock:
            return key in self.cache


def cached_with_ttl(func: Callable, maxsize: int = 128, ttl: float = 60.0) -> Callable:
    """Decorator that caches the result of a function with a time-to-live (TTL)."""

    cache = TTLCache(maxsize=maxsize, ttl=ttl)

    def wrapper(*args, **kwargs):
        key = (args, frozenset(kwargs.items()))
        result = cache[key]
        if result is not None:
            return result

        result = func(*args, **kwargs)
        cache[key] = result
        return result

    return wrapper


