def validate_model(model: Type):
    """Decorator to validate incoming JSON against a model."""
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            # Extract the body from the request
            body = kwargs.get('body')
            if not body:
                raise ValueError("No request body provided")

            try:
                data = json.loads(body)
            except json.JSONDecodeError:
                raise ValueError("Invalid JSON format in request body")

            # Validate against the model
            if not isinstance(data, dict):
                raise ValueError("Request body must be a JSON object")

            # Check if all required fields are present
            required = set(getattr(model, 'required', []))
            if required and not required.issubset(data.keys()):
                raise ValueError(f"Missing required fields: {required - set(data.keys())}")

            # Check if all fields match the model's type
            for field, field_type in getattr(model, '__annotations__', {}).items():
                if field not in data:
                    continue

                # Handle nested models
                if issubclass(field_type, type) and issubclass(field_type, dict):
                    nested_model = field_type
                    nested_required = set(getattr(nested_model, 'required', []))

                    if not nested_required.issubset(data[field].keys()):
                        raise ValueError(f"Missing required fields in nested model: {nested_required - set(data[field].keys())}")

                    for nested_field, nested_type in getattr(nested_model, '__annotations__', {}).items():
                        if nested_field not in data[field]:
                            continue

                        if not isinstance(data[field][nested_field], nested_type):
                            raise TypeError(f"Field {nested_field} in nested model must be type {nested_type}, got {type(data[field][nested_field])}")

                elif not isinstance(data[field], field_type):
                    raise TypeError(f"Field {field} must be type {field_type}, got {type(data[field])}")

            return func(*args, **kwargs)

        return wrapper

    return decorator

