from typing import List, Optional

def find_closest_match(query: str, names: List[str]) -> Optional[str]:
    """
    Find the closest match from a list of names based on string similarity.

    Args:
        query: The query string to search for
        names: List of names to search through

    Returns:
        The closest matching name, or None if no match is found
    """
    # If no names provided, return None
    if not names:
        return None

    # Use Levenshtein distance to find the closest match
    min_distance = float('inf')
    closest_name = None

    for name in names:
        distance = levenshtein_distance(query, name)
        if distance < min_distance:
            min_distance = distance
            closest_name = name

    return closest_name

def levenshtein_distance(s: str, t: str) -> int:
    """
    Calculate the Levenshtein distance between two strings.
    """
    if s == "":
        return len(t)
    if t == "":
        return len(s)

    # Create a matrix to store distances
    matrix = [[0] * (len(t) + 1) for _ in range(len(s) + 1)]

    # Initialize first row and column
    for i in range(len(s) + 1):
        matrix[i][0] = i
    for j in range(len(t) + 1):
        matrix[0][j] = j

    # Fill the matrix
    for i in range(1, len(s) + 1):
        for j in range(1, len(t) + 1):
            if s[i-1] == t[j-1]:
                matrix[i][j] = matrix[i-1][j-1]
            else:
                matrix[i][j] = 1 + min(
                    matrix[i-1][j],    # deletion
                    matrix[i][j-1],    # insertion
                    matrix[i-1][j-1]    # substitution
                )

    return matrix[len(s)][len(t)]

